define state on actor Foo as { let int counter: 0; let int xyz: 0; }
mtd (Foo mut self.state.counter) update(): void {
 self.handle_state(critical-write |s| -> { unknown_effect(s.counter); });
}

declare actor Foo;
define state on actor Foo as { let int counter: 0; }
mtd (Foo mut self.state.counter) update(): void {
 self.handle_state(critical-write |s| -> { await tick(); s.counter += 1; });
}

declare actor Foo;
define state on actor Foo as { let int counter: 0; let int xyz: 0; }
mtd (Foo mut self.state.counter) inc(): void {
 self.handle_state(critical-write |s| -> { s.counter += 1; });
}
mtd (Foo mut self.state.xyz) bump(): void {
 self.handle_state(critical-write |s| -> { s.xyz += 1; });
}

declare actor Foo;
mtd (Foo mut this.state.counter) increment(): void {
 this.handle_state(critical-write |s| -> { s.counter += 1; });
}

declare actor Foo;
mtd (Foo mut node.state.{counter, xyz}) update(): void {
 node.handle_state(critical-write |s| -> { s.counter += 1; s.xyz += 1; });
}

declare actor Foo;
mtd (Foo mut this.state) reset(): void {
 this.handle_state(critical-write |s| -> { s.counter = 0; });
}

declare actor Foo;
mtd (Foo mut this.state.counter) bad(): void {
 this.handle_state(critical-write |s| -> { s.xyz = 9; });
}

declare actor Foo;
mtd (Foo mut this.state.counter) bad(): void {
 self.handle_state(critical-write |s| -> { s.counter = 1; });
}

declare actor Foo;
mtd (Foo mut this.state.counter) bad(): void {
 this.handle_state(critical-write |this| -> { this.counter = 1; });
}

declare actor Foo;
mtd (Foo self) f(): void {}
mtd (Foo this) f(): void {}

declare actor Foo;
mtd (Foo this) foo(): int { return 41; }
mtd (Foo this) bar(): void { this.send(this.foo()); this.send(this.send(42)); }
